// Geography and occupation normalization shared by the map and employer profiles.
// Reference data is generated by scripts/build-geo-data.mjs from public Census
// and O*NET files; see docs/map.md.
const { metros: metroList } = require('../data/geo/metros.json');
const { zips, prefixes } = require('../data/geo/zip-metros.json');
const { states: stateList } = require('../data/geo/states.json');
const occupations = require('../data/geo/occupations.json');

const metros = new Map(metroList.map(metro => [metro.code, metro]));
const states = new Map(stateList.map(state => [state.code, state]));
const stateCodes = new Map(stateList.flatMap(state => [[state.code.toLowerCase(), state.code], [state.name.toLowerCase(), state.code]]));
stateCodes.set('washington dc', 'DC').set('washington, dc', 'DC').set('virgin islands', 'VI').set('d.c.', 'DC');

// Worksite fields per program, in the importer's precedence order.
const fields = {
    h1b: { zip: ['WORKSITE_POSTAL_CODE', 'WORKSITE_POSTAL_CODE_1'],
        city: ['WORKSITE_CITY', 'WORKSITE_CITY_1', 'LCA_CASE_WORKLOC1_CITY', 'CITY_1', 'WORK_LOCATION_CITY1'],
        state: ['WORKSITE_STATE', 'WORKSITE_STATE_1', 'LCA_CASE_WORKLOC1_STATE', 'STATE_1', 'WORK_LOCATION_STATE1'],
        soc: ['PWD_SOC_CODE', 'SOC_CODE', 'LCA_CASE_SOC_CODE'], level: ['PW_WAGE_LEVEL', 'PW_WAGE_LEVEL_1'],
        wage: 'WAGE_RATE_OF_PAY_FROM', unit: 'WAGE_UNIT_OF_PAY' },
    perm: { zip: ['WORKSITE_POSTAL_CODE', 'JOB_INFO_WORK_POSTAL_CODE', 'PRIMARY_WORKSITE_POSTAL_CODE'],
        city: ['WORKSITE_CITY', 'JOB_INFO_WORK_CITY', 'JOB_OPP_CITY'], state: ['WORKSITE_STATE', 'JOB_INFO_WORK_STATE', 'JOB_OPP_STATE'],
        soc: ['PWD_SOC_CODE', 'PW_SOC_CODE'], level: ['PWD_OES_WAGE_LEVEL', 'PW_SKILL_LEVEL', 'PW_LEVEL_9089'],
        wage: 'JOB_OPP_WAGE_FROM', unit: 'JOB_OPP_WAGE_PER' },
    pwd: { zip: ['PRIMARY_WORKSITE_POSTAL_CODE', 'WORKSITE_POSTAL_CODE'], city: ['PRIMARY_WORKSITE_CITY', 'WORKSITE_CITY'],
        state: ['PRIMARY_WORKSITE_STATE', 'WORKSITE_STATE'], soc: ['PWD_SOC_CODE', 'SUGGESTED_SOC_CODE'],
        level: ['PWD_OES_WAGE_LEVEL', 'PWD_WAGE_LEVEL'], wage: 'PWD_WAGE_RATE', unit: 'PWD_UNIT_OF_PAY' },
};

// Annual wages use 2,080 hours, 52 weeks, 26 pay periods or 12 months a year.
// Bins are $2,000 wide; the last bin holds $1,000,000 and above.
const WAGE_BIN = 2000, LAST_BIN = 500, MIN_ANNUAL = 10000, MAX_ANNUAL = 2000000;
const UNIT_FACTORS = [[['ye', 'yr'], 1], [['ho', 'hr'], 2080], [['we', 'wk'], 52], [['bi'], 26], [['mo', 'mt'], 12]];

// First non-empty string (or number, e.g. a ZIP stored as 2134) among fields.
function textExpression(names) {
    return names.reduceRight((fallback, name) => ({ $cond: [
        { $eq: [{ $type: '$' + name }, 'string'] },
        { $cond: [{ $ne: [{ $trim: { input: '$' + name } }, ''] }, { $trim: { input: '$' + name } }, fallback] },
        { $cond: [{ $isNumber: '$' + name }, { $toString: { $toLong: '$' + name } }, fallback] },
    ] }), null);
}

function wageBinExpression(program) {
    const { wage, unit } = fields[program];
    const prefix = { $toLower: { $substrCP: [{ $ifNull: [textExpression([unit]), ''] }, 0, 2] } };
    const factor = { $switch: { branches: UNIT_FACTORS.map(([units, value]) => ({ case: { $in: [prefix, units] }, then: value })), default: null } };
    const annual = { $cond: [{ $and: [{ $isNumber: '$' + wage }, { $ne: [factor, null] }] }, { $multiply: ['$' + wage, factor] }, null] };
    return { $let: { vars: { annual }, in: { $cond: [{ $and: [{ $gte: ['$$annual', MIN_ANNUAL] }, { $lte: ['$$annual', MAX_ANNUAL] }] },
        { $min: [LAST_BIN, { $floor: { $divide: ['$$annual', WAGE_BIN] } }] }, null] } } };
}

// Compact per-case location/occupation/wage fields, computed inside MongoDB.
function cellProjection(program, date) {
    const config = fields[program], text = names => ({ $ifNull: [textExpression(names), ''] });
    return {
        z: { $substrCP: [text(config.zip), 0, 5] },
        c: { $toLower: { $substrCP: [text(config.city), 0, 60] } },
        s: { $toLower: { $substrCP: [text(config.state), 0, 30] } },
        ...(date ? { y: { $cond: [{ $and: [{ $eq: [{ $type: '$' + date }, 'date'] }, { $gte: ['$' + date, new Date('1990-01-01')] },
            { $lt: ['$' + date, new Date('2100-01-01')] }] }, { $year: '$' + date }, null] } } : {}),
        o: { $substrCP: [text(config.soc), 0, 7] },
        l: { $toUpper: { $substrCP: [text(config.level), 0, 12] } },
        b: wageBinExpression(program),
    };
}

function stateCode(value) {
    if (typeof value !== 'string') return null;
    return stateCodes.get(value.trim().toLowerCase().replace(/\s+/g, ' ').replace(/\.$/, '')) || null;
}

// Lowercase values MongoDB may store for a state (postal code and name).
function stateValues(code) {
    const state = states.get(String(code).toUpperCase());
    return state ? [...new Set([state.code.toLowerCase(), state.name.toLowerCase(),
        ...[...stateCodes].filter(([, value]) => value === state.code).map(([key]) => key)])] : null;
}

function zipCode(value) {
    const digits = String(value ?? '').match(/^\d{3,5}/)?.[0];
    return digits ? digits.padStart(5, '0') : null;
}

function metroForZip(value) {
    const zip = zipCode(value);
    return zip ? zips[zip] || prefixes[zip.slice(0, 3)] || null : null;
}

const cityKey = (state, city) => state && city ? state + '|' + city.trim().toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim() : null;

// SOC 2000/2010/2018 or O*NET codes to a six-digit SOC 2018 code where known.
function occupationCode(value) {
    const match = String(value ?? '').match(/^(\d{2})-?(\d{4})/);
    if (!match) return null;
    const code = `${match[1]}-${match[2]}`;
    return occupations.successors[code] || code;
}
const occupationTitle = code => occupations.titles[code] || null;

function wageLevel(value) {
    const match = String(value ?? '').toUpperCase().replace(/^LEVEL\s*/, '').trim().match(/^(IV|III|II|I|[1-4])$/);
    return match ? { I: 1, II: 2, III: 3, IV: 4, 1: 1, 2: 2, 3: 3, 4: 4 }[match[1]] : null;
}

// Learns which metro a reported worksite city belongs to from cases that also
// report a ZIP code. Used only for cases without a usable ZIP.
class CityMetros {
    constructor(entries = {}) { this.map = new Map(Object.entries(entries)); this.tally = new Map(); }
    learn(state, city, metro, count) {
        const key = cityKey(state, city);
        if (!key || !metro) return;
        const counts = this.tally.get(key) || new Map();
        counts.set(metro, (counts.get(metro) || 0) + count);
        this.tally.set(key, counts);
    }
    // A city is assigned when at least 5 cases and 80% of them agree.
    finish() {
        for (const [key, counts] of this.tally) {
            const total = [...counts.values()].reduce((sum, count) => sum + count, 0);
            const [metro, count] = [...counts].sort((a, b) => b[1] - a[1])[0];
            if (total >= 5 && count / total >= 0.8) this.map.set(key, metro); else this.map.delete(key);
        }
        this.tally.clear();
        return this;
    }
    get(state, city) { return this.map.get(cityKey(state, city)) || null; }
    toJSON() { return Object.fromEntries(this.map); }
}

// Location of one reduced cell: { state, metro } (either may be null).
function locate(cell, cities) {
    const state = stateCode(cell.s);
    let metro = metroForZip(cell.z);
    if (metro && state && !metros.get(metro)?.states.includes(state)) metro = null;
    if (!metro && state && cities) metro = cities.get(state, cell.c);
    return { state, metro };
}

// Wage histogram helpers. Medians interpolate within the $2,000 bin.
const histogram = () => new Uint32Array(LAST_BIN + 1);
function median(bins) {
    let total = 0;
    for (const count of bins) total += count;
    if (!total) return null;
    let seen = 0;
    const half = total / 2;
    for (let bin = 0; bin < bins.length; bin++) {
        if (!bins[bin]) continue;
        if (seen + bins[bin] >= half) {
            const within = (half - seen) / bins[bin];
            return Math.round((bin + within) * WAGE_BIN / 100) * 100;
        }
        seen += bins[bin];
    }
    return null;
}

module.exports = { fields, metros, states, textExpression, wageBinExpression, cellProjection, stateCode, stateValues, zipCode,
    metroForZip, occupationCode, occupationTitle, wageLevel, CityMetros, locate, histogram, median, WAGE_BIN, LAST_BIN };
